import pandas as pd
import numpy as np
import ast

employees = pd.read_csv('/app/dataset/employees.csv')
tasks = pd.read_csv('/app/dataset/tasks.csv')
timesheet = pd.read_csv('/app/dataset/timesheet.csv')

# Preprocess
employees['PESEL_str'] = employees['PESEL'].astype(str).str.zfill(11)
timesheet['employee_id_str'] = timesheet['employee_id'].astype(str).str.zfill(11)

# Task pay mapping
task_pay = tasks.set_index('task_id')['pay_per_completion'].to_dict()

# Correct invalid employee IDs mapping
mapping = {
    '15720759071': '75020759171', # Jan Król
    '16102016795': '96102016751', # Tomasz Wójcik
    '62020111425': '65020111422', # Magdalena Wójcik
    '68011910138': '68011810139', # Tomasz Kurek
    '84731091580': '87031491580'  # Agnieszka Zając
}

# Billing Month Helper
def get_billing_month(date_str):
    if date_str == '2025-04-31':
        date_str = '2025-04-30'
    elif date_str == '2025-06-31':
        date_str = '2025-06-30'

    parsed = pd.to_datetime(date_str, errors='coerce')
    if pd.isnull(parsed):
        return None

    if pd.Timestamp('2025-03-04') <= parsed <= pd.Timestamp('2025-03-31'):
        return '2025-03'
    elif pd.Timestamp('2025-04-01') <= parsed <= pd.Timestamp('2025-05-05'):
        return '2025-04'
    elif pd.Timestamp('2025-05-06') <= parsed <= pd.Timestamp('2025-06-02'):
        return '2025-05'
    elif pd.Timestamp('2025-06-03') <= parsed <= pd.Timestamp('2025-06-30'):
        return '2025-06'
    else:
        return 'Other'

timesheet['billing_month'] = timesheet['date'].apply(get_billing_month)

def get_row_bonus(row):
    try:
        pt_list = ast.literal_eval(row['performed_tasks'])
    except:
        import re
        pt_list = [int(x) for x in re.findall(r'\d+', str(row['performed_tasks']))]
    return sum(task_pay.get(t, 0) for t in pt_list)

# Standard mathematical rounding helper
def std_round(val):
    return int(np.floor(val + 0.5))

# We'll first drop exact raw duplicates
ts_raw_dedup = timesheet.drop_duplicates(subset=['date', 'hours_worked', 'performed_tasks', 'employee_id_str', 'facility_id', 'salary_amount', 'bonus'])

# Let's compute Option 1: Strictly exclude invalid employee rows
def get_option_1():
    valid_pesels = set(employees['PESEL_str'])
    df = ts_raw_dedup[ts_raw_dedup['employee_id_str'].isin(valid_pesels)].copy()

    salaries = {p: {'2025-03': 0, '2025-04': 0, '2025-05': 0, '2025-06': 0} for p in employees['PESEL_str']}
    for idx, row in df.iterrows():
        p = row['employee_id_str']
        m = row['billing_month']
        if m in salaries[p]:
            rate = employees[employees['PESEL_str'] == p]['hourly_rate'].values[0]
            bonus = get_row_bonus(row)
            salaries[p][m] += row['hours_worked'] * rate + bonus

    return {p: [std_round(salaries[p]['2025-03']), std_round(salaries[p]['2025-04']), std_round(salaries[p]['2025-05']), std_round(salaries[p]['2025-06'])] for p in salaries}

# Option 2: Map invalid employee IDs, sum everything (all hours and all bonuses)
def get_option_2():
    df = ts_raw_dedup.copy()
    df['employee_id_str'] = df['employee_id_str'].replace(mapping)

    salaries = {p: {'2025-03': 0, '2025-04': 0, '2025-05': 0, '2025-06': 0} for p in employees['PESEL_str']}
    for idx, row in df.iterrows():
        p = row['employee_id_str']
        m = row['billing_month']
        if m in salaries[p]:
            rate = employees[employees['PESEL_str'] == p]['hourly_rate'].values[0]
            bonus = get_row_bonus(row)
            salaries[p][m] += row['hours_worked'] * rate + bonus

    return {p: [std_round(salaries[p]['2025-03']), std_round(salaries[p]['2025-04']), std_round(salaries[p]['2025-05']), std_round(salaries[p]['2025-06'])] for p in salaries}

# Option 3: Map invalid employee IDs, merge overlapping days: count hours once, sum bonuses
def get_option_3():
    df = ts_raw_dedup.copy()
    df['employee_id_str'] = df['employee_id_str'].replace(mapping)

    # Calculate bonus for each row
    df['row_bonus'] = df.apply(get_row_bonus, axis=1)

    # Group by employee, date, and billing_month
    # For each group, we take:
    # hours_worked = max(hours_worked)  (since they are identical, max works)
    # bonus = sum(row_bonus)
    grouped = df.groupby(['employee_id_str', 'date', 'billing_month']).agg({
        'hours_worked': 'max',
        'row_bonus': 'sum'
    }).reset_index()

    salaries = {p: {'2025-03': 0, '2025-04': 0, '2025-05': 0, '2025-06': 0} for p in employees['PESEL_str']}
    for idx, row in grouped.iterrows():
        p = row['employee_id_str']
        m = row['billing_month']
        if m in salaries[p]:
            rate = employees[employees['PESEL_str'] == p]['hourly_rate'].values[0]
            salaries[p][m] += row['hours_worked'] * rate + row['row_bonus']

    return {p: [std_round(salaries[p]['2025-03']), std_round(salaries[p]['2025-04']), std_round(salaries[p]['2025-05']), std_round(salaries[p]['2025-06'])] for p in salaries}

opt1 = get_option_1()
opt2 = get_option_2()
opt3 = get_option_3()

# Let's print comparison for the 5 affected employees
affected_p_to_name = {
    '75020759171': 'Jan Król',
    '96102016751': 'Tomasz Wójcik',
    '65020111422': 'Magdalena Wójcik',
    '68011810139': 'Tomasz Kurek',
    '87031491580': 'Agnieszka Zając'
}

for p, name in affected_p_to_name.items():
    print(f"\nEmployee: {name} ({p})")
    print("  Option 1 (Exclude):", opt1[p])
    print("  Option 2 (Sum all):", opt2[p])
    print("  Option 3 (Merge hrs):", opt3[p])

